import "server-only";
import data from "./search-vocabulary.json";
import { haystackOf, type Haystack } from "./search-terms";

// What each HaynesPro repair group holds, as words (Task 74) — generated by
// scripts/build-search-vocabulary.mjs from a crawl of four reference cars.
// Group ids are one taxonomy across every vehicle, so this steers the repair
// search's walk for any car. A group it doesn't know (one the reference cars
// lack) gets null and the walk falls back to the group's own name.

const groups = (data as { groups: Record<string, string> }).groups;
const cache = new Map<string, Haystack>();

export function groupVocabulary(groupId: string): Haystack | null {
  const hit = cache.get(groupId);
  if (hit) return hit;
  const words = groups[groupId];
  if (words == null) return null;
  const haystack = haystackOf(words);
  cache.set(groupId, haystack);
  return haystack;
}
